import { mkdir, writeFile } from "node:fs/promises";

import { vendorSample } from "../shared/rote/samples.js";
await mkdir("data/sample/vendors", { recursive: true });
for (let week = 1; week <= 20; week++)
  await writeFile(
    `data/sample/vendors/week-${String(week).padStart(2, "0")}.csv`,
    vendorSample(week),
  );
await writeFile(
  "data/sample/vendors/README.md",
  "# Sample vendor data\n\nSynthetic deterministic sample data generated by scripts/gen-vendors.ts. 20 weekly files, 25 distinct SKUs per week plus four duplicate rows. Messy headers, text spacing, currency and units are intentional. Not real vendor data.\n",
);
console.log("Generated 20 sample vendor CSV files, 29 rows per week.");
